"""Task-local validation for webhook_endpoint.py (syntax + structure)."""
import ast
import sys
from pathlib import Path

path = Path("webhook_endpoint.py")
source = path.read_text(encoding="utf-8")
tree = ast.parse(source, filename=str(path))

module_names = set()
for node in tree.body:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        module_names.add(node.name)
    elif isinstance(node, ast.ClassDef):
        module_names.add(node.name)

required = {
    "stripe_webhook",
    "handle_payment_succeeded",
    "handle_payment_failed",
    "is_event_processed",
    "mark_event_processed",
}
missing = required - module_names
if missing:
    sys.exit(f"FAIL: missing definitions: {sorted(missing)}")

# Verify the Flask route decorator for /webhook exists.
route_targets = []
for node in tree.body:
    for dec in getattr(node, "decorator_list", []):
        if isinstance(dec, ast.Call) and getattr(dec.func, "attr", None) == "route":
            if dec.args and isinstance(dec.args[0], ast.Constant):
                route_targets.append(dec.args[0].value)
if "/webhook" not in route_targets:
    sys.exit(f"FAIL: /webhook route not found; routes={route_targets}")

# Verify event dispatch map contains both required events.
handler_map = None
for node in tree.body:
    if (
        isinstance(node, ast.Assign)
        and any(isinstance(t, ast.Name) and t.id == "EVENT_HANDLERS" for t in node.targets)
    ):
        handler_map = node.value
if not isinstance(handler_map, ast.Dict):
    sys.exit("FAIL: EVENT_HANDLERS map not found")
keys = {k.value for k in handler_map.keys if isinstance(k, ast.Constant)}
for ev in ("payment_intent.succeeded", "payment_intent.payment_failed"):
    if ev not in keys:
        sys.exit(f"FAIL: {ev} not in EVENT_HANDLERS")

print("PASS: webhook_endpoint.py compiles; endpoint + handlers + dispatch map OK")
